def palindrome_cuts(s: str) -> list[list[str]]:
    n, res = len(s), []
    for mask in range(1 << (n - 1)):     # every way to cut: bit i = cut after s[i]
        pieces, start = [], 0
        for i in range(1, n):
            if mask >> (i - 1) & 1:
                pieces.append(s[start:i])
                start = i
        pieces.append(s[start:])
        if all(p == p[::-1] for p in pieces):
            res.append(pieces)
    return res
